export function delay(attempt: number, baseMs: number, maxMs: number, jitter = 1) {
  if (attempt < 1 || !Number.isInteger(attempt)) throw new Error("attempt must be positive integer")
  if (baseMs < 0 || maxMs < 0 || jitter < 0) throw new Error("negative option")
  return Math.round(Math.min(maxMs, baseMs * 2 ** attempt) * jitter)
}

export function delay(attempt: number, baseMs: number, maxMs: number, jitter = 1) {
  if (attempt < 1 || !Number.isInteger(attempt)) throw new Error("attempt must be positive integer")
  if (baseMs < 0 || maxMs < 0 || jitter < 0) throw new Error("negative option")
  return Math.min(maxMs, Math.round(baseMs * 2 ** (attempt - 1) * jitter))
}
